import React, { useEffect, useState } from "react";
import axios from "axios";

function Home() {
  const [products, setProducts] = useState([]);
  const [cart, setCart] = useState([]);

  useEffect(() => {
    axios
      .get("http://localhost:5000/api/products")
      .then((res) => setProducts(res.data))
      .catch((err) => console.log(err));
  }, []);

  // ADD TO CART
  const addToCart = (product) => {
    const alreadyExist = cart.find((item) => item._id === product._id);

    if (alreadyExist) {
      const updatedCart = cart.map((item) =>
        item._id === product._id
          ? { ...item, quantity: item.quantity + 1 }
          : item
      );

      setCart(updatedCart);
    } else {
      setCart([...cart, { ...product, quantity: 1 }]);
    }
  };

  // REMOVE FROM CART
  const removeFromCart = (id) => {
    const updatedCart = cart.filter((item) => item._id !== id);
    setCart(updatedCart);
  };

  // TOTAL PRICE
  const totalPrice = cart.reduce(
    (total, item) => total + item.price * item.quantity,
    0
  );

  return (
    <div
      style={{
        background: "#0f172a",
        minHeight: "100vh",
        padding: "30px",
        color: "white",
        fontFamily: "Arial",
      }}
    >
      {/* HEADER */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "40px",
        }}
      >
        <h1
          style={{
            fontSize: "42px",
            color: "#38bdf8",
          }}
        >
          ShopEasy
        </h1>

        <div
          style={{
            background: "#1e293b",
            padding: "15px 25px",
            borderRadius: "12px",
            fontSize: "20px",
          }}
        >
          🛒 Cart: {cart.length}
        </div>
      </div>

      {/* PRODUCTS */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit,minmax(250px,1fr))",
          gap: "25px",
        }}
      >
        {products.map((p) => (
          <div
            key={p._id}
            style={{
              background: "#1e293b",
              padding: "20px",
              borderRadius: "18px",
              boxShadow: "0 5px 20px rgba(0,0,0,0.3)",
              transition: "0.3s",
            }}
          >
            <img
              src={p.image}
              alt={p.name}
              style={{
                width: "100%",
                height: "220px",
                objectFit: "cover",
                borderRadius: "12px",
              }}
            />

            <h2 style={{ marginTop: "15px" }}>{p.name}</h2>

            <p
              style={{
                color: "#cbd5e1",
                margin: "10px 0",
              }}
            >
              {p.description}
            </p>

            <h3 style={{ color: "#22c55e" }}>₹{p.price}</h3>

            <button
              onClick={() => addToCart(p)}
              style={{
                marginTop: "15px",
                width: "100%",
                padding: "12px",
                background: "#38bdf8",
                color: "black",
                border: "none",
                borderRadius: "10px",
                cursor: "pointer",
                fontWeight: "bold",
                fontSize: "16px",
              }}
            >
              Add To Cart
            </button>
          </div>
        ))}
      </div>

      {/* CART SECTION */}
      <div
        style={{
          marginTop: "50px",
          background: "#1e293b",
          padding: "25px",
          borderRadius: "18px",
        }}
      >
        <h2 style={{ marginBottom: "20px" }}>🛍 Your Cart</h2>

        {cart.length === 0 ? (
          <p>Cart is Empty</p>
        ) : (
          cart.map((item) => (
            <div
              key={item._id}
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                background: "#334155",
                padding: "15px",
                borderRadius: "10px",
                marginBottom: "15px",
              }}
            >
              <div>
                <h3>{item.name}</h3>
                <p>
                  ₹{item.price} × {item.quantity}
                </p>
              </div>

              <button
                onClick={() => removeFromCart(item._id)}
                style={{
                  background: "red",
                  color: "white",
                  border: "none",
                  padding: "10px 15px",
                  borderRadius: "8px",
                  cursor: "pointer",
                }}
              >
                Remove
              </button>
            </div>
          ))
        )}

        <h2 style={{ marginTop: "20px", color: "#22c55e" }}>
          Total: ₹{totalPrice}
        </h2>
      </div>
    </div>
  );
}

export default Home;
